14	// ConfigHandler reads and serves the config as JSON from the local config file.
15	func ConfigHandler(configPath string) http.HandlerFunc {
16		return func(w http.ResponseWriter, r *http.Request) {
17			if r.Method != http.MethodGet {
18				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
19				return
20			}
21	
22			w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate")
23	
24			configData, err := readCanonicalConfigFile(configPath)
25			if err != nil {
26				http.Error(w, fmt.Sprintf("Failed to read config: %v", err), http.StatusInternalServerError)
27				return
28			}
29	
30			if err := writeYAMLTaggedJSON(w, configData); err != nil {
31				log.Printf("Error encoding config to JSON: %v", err)
32			}
33		}
34	}
35	
36	// ConfigYAMLHandler reads and serves the config as raw YAML text.
37	// This is used by the DSL Builder to load the current router config
38	// and decompile it into DSL via WASM.
39	func ConfigYAMLHandler(configPath string) http.HandlerFunc {
40		return func(w http.ResponseWriter, r *http.Request) {
41			if r.Method != http.MethodGet {
42				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
43				return
44			}
45	
46			w.Header().Set("Content-Type", "text/yaml; charset=utf-8")
47			w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate")
48	
49			data, err := os.ReadFile(configPath)
50			if err != nil {
51				http.Error(w, fmt.Sprintf("Failed to read config: %v", err), http.StatusInternalServerError)
52				return
53			}
54	
55			_, _ = w.Write(data)
56		}
57	}
58	
59	// UpdateConfigHandler replaces config.yaml with a validated full config payload.
60	// The dashboard editor always sends the whole canonical document, so this path
61	// intentionally does not deep-merge into any legacy on-disk layout.
62	// After writing, it synchronously propagates the change to the managed runtime
63	// so Router and Envoy pick up the new config before the API returns success.
64	func UpdateConfigHandler(configPath string, readonlyMode bool, configDir string) http.HandlerFunc {
65		return func(w http.ResponseWriter, r *http.Request) {
66			if r.Method != http.MethodPost && r.Method != http.MethodPut {
67				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
68				return
69			}
70	
71			// Check read-only mode
72			if readonlyMode {
73				w.Header().Set("Content-Type", "application/json")
74				w.WriteHeader(http.StatusForbidden)
75				if err := writeYAMLTaggedJSON(w, map[string]string{
76					"error":   "readonly_mode",
77					"message": "Dashboard is in read-only mode. Configuration editing is disabled.",
78				}); err != nil {
79					log.Printf("Error encoding readonly response: %v", err)
80				}
81				return
82			}
83	
84			configData, err := decodeYAMLTaggedBody[routerconfig.CanonicalConfig](r.Body)
85			if err != nil {
86				http.Error(w, fmt.Sprintf("Invalid request body: %v", err), http.StatusBadRequest)
87				return
88			}
89			if validationErr := validateCanonicalEndpointRefs(configData); validationErr != nil {
90				http.Error(w, fmt.Sprintf("Config validation failed: %v", validationErr), http.StatusBadRequest)
91				return
92			}
93	
94			// Read existing config so runtime rollback can restore the previous file if needed.
95			existingData, err := os.ReadFile(configPath)
96			if err != nil {
97				http.Error(w, fmt.Sprintf("Failed to read existing config: %v", err), http.StatusInternalServerError)
98				return
99			}
100	
101			yamlData, err := marshalYAMLBytes(configData)
102			if err != nil {
103				http.Error(w, fmt.Sprintf("Failed to convert to YAML: %v", err), http.StatusInternalServerError)
104				return
105			}
106	
107			parsedConfig, err := routerconfig.ParseYAMLBytes(yamlData)
108			if err != nil {
109				http.Error(w, fmt.Sprintf("Config validation failed: %v", err), http.StatusBadRequest)
110				return
111			}
112	
113			// Explicitly validate vLLM endpoints (Parse doesn't validate endpoints by default)
114			if len(parsedConfig.VLLMEndpoints) > 0 {
115				for _, endpoint := range parsedConfig.VLLMEndpoints {
116					if endpoint.ProviderProfileName != "" && endpoint.Address == "" {
117						continue
118					}
119					if err := validateEndpointAddress(endpoint.Address); err != nil {
120						http.Error(w, fmt.Sprintf("Config validation failed: vLLM endpoint '%s' address validation failed: %v\n\nSupported formats:\n- IPv4: 192.168.1.1, 127.0.0.1\n- IPv6: ::1, 2001:db8::1\n- DNS names: localhost, example.com, api.example.com\n\nUnsupported formats:\n- Protocol prefixes: http://, https://\n- Paths: /api/v1, /health\n- Ports in address: use 'port' field instead", endpoint.Name, err), http.StatusBadRequest)
121						return
122					}
123				}
124			}
125	
126			if err := writeConfigAtomically(configPath, yamlData); err != nil {
127				http.Error(w, fmt.Sprintf("Failed to write config: %v", err), http.StatusInternalServerError)
128				return
129			}
130	
131			if err := applyWrittenConfig(configPath, configDir, existingData, true); err != nil {
132				http.Error(w, formatRuntimeApplyError("Failed to apply config to runtime", err), http.StatusInternalServerError)
133				return
134			}
135	
136			refreshConfigProjection(configprojection.RefreshInput{
137				Version:     newActivationVersion(),
138				Source:      configprojection.SourceManual,
139				YAMLBytes:   yamlData,
140				DSLSnapshot: readArchivedDSL(configDir),
141			})
142	
143			if err := writeYAMLTaggedJSON(w, map[string]string{"status": "success"}); err != nil {
144				log.Printf("Error encoding response: %v", err)
145			}
146		}
147	}
