69	// DeployPreviewHandler returns the current config and the merged preview
70	// so the frontend can show a side-by-side diff before confirming deploy.
71	// POST /api/router/config/deploy/preview
72	func DeployPreviewHandler(configPath string) http.HandlerFunc {
73		return func(w http.ResponseWriter, r *http.Request) {
74			if r.Method != http.MethodPost {
75				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
76				return
77			}
78	
79			var req DeployRequest
80			if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
81				http.Error(w, fmt.Sprintf("Invalid request body: %v", err), http.StatusBadRequest)
82				return
83			}
84	
85			if strings.TrimSpace(req.YAML) == "" {
86				http.Error(w, "YAML content is required", http.StatusBadRequest)
87				return
88			}
89	
90			if _, err := decodeYAMLTaggedBytes[routingFragmentDocument]([]byte(req.YAML)); err != nil {
91				w.Header().Set("Content-Type", "application/json")
92				w.WriteHeader(http.StatusBadRequest)
93				_ = json.NewEncoder(w).Encode(map[string]string{
94					"error":   "yaml_parse_error",
95					"message": fmt.Sprintf("Invalid YAML syntax: %v", err),
96				})
97				return
98			}
99	
100			currentData, err := os.ReadFile(configPath)
101			currentForDiffBytes := currentData
102			if err != nil {
103				currentForDiffBytes = []byte("# No existing config\n")
104			}
105	
106			previewBytes, err := mergeDeployPayload(currentData, req)
107			if err != nil {
108				w.Header().Set("Content-Type", "application/json")
