116	
117			currentForDiff := canonicalizeYAMLForDiff(currentForDiffBytes)
118			previewForDiff := canonicalizeYAMLForDiff(previewBytes)
119	
120			w.Header().Set("Content-Type", "application/json")
121			_ = json.NewEncoder(w).Encode(DeployPreviewResponse{
122				Current: currentForDiff,
123				Preview: previewForDiff,
124			})
125		}
126	}
