128	// DeployHandler handles DSL config deployment.
129	// It writes the user-facing config.yaml, then synchronously propagates the
130	// change to Router and Envoy before returning success.
131	//
132	// POST /api/router/config/deploy
133	func DeployHandler(configPath string, readonlyMode bool, configDir string) http.HandlerFunc {
134		return func(w http.ResponseWriter, r *http.Request) {
135			if r.Method != http.MethodPost {
136				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
