150			var req DeployRequest
151			if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
152				http.Error(w, fmt.Sprintf("Invalid request body: %v", err), http.StatusBadRequest)
153				return
154			}
155	
156			if strings.TrimSpace(req.YAML) == "" {
157				http.Error(w, "YAML content is required", http.StatusBadRequest)
158				return
159			}
160	
161			log.Printf("[Deploy] Received: YAML=%d bytes, DSL=%d bytes", len(req.YAML), len(req.DSL))
162	
163			deployDirectWrite(w, configPath, configDir, req)
164		}
