167	// RollbackHandler rolls back to a specific backup version and synchronously
168	// propagates the restored config to Router and Envoy.
169	// POST /api/router/config/rollback
170	func RollbackHandler(configPath string, readonlyMode bool, configDir string) http.HandlerFunc {
171		return func(w http.ResponseWriter, r *http.Request) {
172			if r.Method != http.MethodPost {
173				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
