215	
216	// ==================== Deploy: write canonical config.yaml ====================
217	
218	func deployDirectWrite(w http.ResponseWriter, configPath string, configDir string, req DeployRequest) {
219		// Acquire deploy lock (only one deploy at a time)
220		if !deployMu.TryLock() {
221			w.Header().Set("Content-Type", "application/json")
222			w.WriteHeader(http.StatusConflict)
223			_ = json.NewEncoder(w).Encode(map[string]string{
224				"error":   "deploy_in_progress",
225				"message": "Another deploy operation is in progress. Please try again.",
226			})
227			return
228		}
229		defer deployMu.Unlock()
230	
231		fragmentBytes := []byte(req.YAML)
232		if _, err := decodeYAMLTaggedBytes[routingFragmentDocument](fragmentBytes); err != nil {
233			w.Header().Set("Content-Type", "application/json")
234			w.WriteHeader(http.StatusBadRequest)
235			_ = json.NewEncoder(w).Encode(map[string]string{
236				"error":   "yaml_parse_error",
237				"message": fmt.Sprintf("Invalid YAML syntax: %v", err),
238			})
239			return
240		}
241	
242		existingData, err := os.ReadFile(configPath)
243		if err != nil {
244			existingData = nil
245		}
246	
247		// Step 2: Deep merge the routing fragment into the deploy base.
248		yamlBytes, err := mergeDeployPayload(existingData, req)
249		if err != nil {
250			w.Header().Set("Content-Type", "application/json")
251			w.WriteHeader(http.StatusBadRequest)
252			_ = json.NewEncoder(w).Encode(map[string]string{
253				"error":   "config_merge_error",
254				"message": err.Error(),
255			})
256			return
257		}
258	
259		if _, err := routerconfig.ParseYAMLBytes(yamlBytes); err != nil {
260			w.Header().Set("Content-Type", "application/json")
261			w.WriteHeader(http.StatusBadRequest)
262			_ = json.NewEncoder(w).Encode(map[string]string{
263				"error":   "config_validation_error",
264				"message": fmt.Sprintf("Merged config validation failed: %v", err),
265			})
266			return
267		}
268	
269		// Step 3: Create backup of current config
270		version := createConfigBackup(configDir, existingData)
271	
272		// Step 4: Archive DSL source (for audit trail)
273		archiveDeployDSL(configDir, req.DSL)
274	
275		// Step 5: Atomic write to config.yaml
276		if err := writeConfigAtomically(configPath, yamlBytes); err != nil {
277			http.Error(w, fmt.Sprintf("Failed to write config: %v", err), http.StatusInternalServerError)
278			return
279		}
280	
281		log.Printf("[Deploy] Config written to %s: version=%s, size=%d bytes", configPath, version, len(yamlBytes))
282	
283		// Step 6: Propagate the new config to the managed runtime before returning.
284		if err := applyWrittenConfig(configPath, configDir, existingData, true); err != nil {
285			http.Error(w, formatRuntimeApplyError("Failed to apply deployed config to runtime", err), http.StatusInternalServerError)
286			return
287		}
288	
289		// Step 7: Clean up old backups (keep only maxBackups most recent)
290		cleanupBackups(configBackupDir(configDir))
291	
292		refreshConfigProjection(configprojection.RefreshInput{
293			Version:     newActivationVersion(),
294			Source:      configprojection.SourceDSL,
295			YAMLBytes:   yamlBytes,
296			DSLSnapshot: req.DSL,
297		})
298	
299		w.Header().Set("Content-Type", "application/json")
300		_ = json.NewEncoder(w).Encode(DeployResponse{
301			Status:  "success",
302			Version: version,
303			Message: "Config deployed successfully. Router and Envoy have been updated.",
304		})
305	}
306	
307	func mergeDeployPayload(currentData []byte, req DeployRequest) ([]byte, error) {
308		fragmentBytes := []byte(req.YAML)
309		baseData, err := resolveDeployBaseYAML(currentData, req.BaseYAML)
310		if err != nil {
311			return nil, err
312		}
313		if len(baseData) == 0 {
314			return fragmentBytes, nil
315		}
316		if req.Mode != "" && req.Mode != DeployModeMerge && req.Mode != DeployModeReplace {
317			return nil, fmt.Errorf("unsupported deploy mode %q", req.Mode)
318		}
319	
320		baseDoc, err := parseYAMLDocument(baseData)
321		if err != nil {
322			return nil, fmt.Errorf("failed to parse deploy base config: %w", err)
323		}
324		baseRoot, err := documentMappingNode(baseDoc)
325		if err != nil {
326			return nil, fmt.Errorf("failed to parse deploy base config: %w", err)
327		}
328	
329		fragmentDoc, err := parseYAMLDocument(fragmentBytes)
330		if err != nil {
331			return nil, fmt.Errorf("failed to parse compiled routing fragment: %w", err)
332		}
333		fragmentRoot, err := documentMappingNode(fragmentDoc)
334		if err != nil {
335			return nil, fmt.Errorf("failed to parse compiled routing fragment: %w", err)
336		}
337		fragmentConfig, err := decodeYAMLTaggedBytes[routingFragmentDocument](fragmentBytes)
338		if err != nil {
339			return nil, fmt.Errorf("failed to parse compiled routing fragment: %w", err)
340		}
341	
342		if mergeErr := mergeDSLOwnedNodes(baseRoot, fragmentRoot, req.Mode); mergeErr != nil {
343			return nil, mergeErr
344		}
345		if mergeErr := mergeFragmentGlobalNode(baseRoot, fragmentConfig.Global); mergeErr != nil {
346			return nil, mergeErr
347		}
348	
349		mergedYAML, err := marshalYAMLDocument(baseDoc)
350		if err != nil {
351			return nil, fmt.Errorf("failed to marshal merged config: %w", err)
352		}
353		return mergedYAML, nil
354	}
355	
356	// mergeDSLOwnedNodes applies only the configuration surface owned by the DSL.
357	// Node-level merging makes the transport forward-compatible: a new signal or
358	// projection is carried without adding another field-by-field merge branch.
359	func mergeDSLOwnedNodes(baseRoot, fragmentRoot *yaml.Node, mode DeployMode) error {
360		fragmentRouting := mappingValueNode(fragmentRoot, "routing")
361		if mode == DeployModeReplace {
362			if fragmentRouting == nil {
363				return fmt.Errorf("compiled routing fragment must contain routing")
364			}
365			setMappingValueNode(baseRoot, "routing", fragmentRouting)
366			for _, section := range []string{"entrypoints", "recipes"} {
367				if value := mappingValueNode(fragmentRoot, section); value != nil {
368					setMappingValueNode(baseRoot, section, value)
369				} else {
370					deleteMappingValueNode(baseRoot, section)
371				}
372			}
373			return nil
374		}
375	
376		if fragmentRouting != nil {
377			baseRouting := mappingValueNode(baseRoot, "routing")
378			if baseRouting == nil {
379				setMappingValueNode(baseRoot, "routing", fragmentRouting)
380			} else if err := mergeMappingNodes(baseRouting, fragmentRouting); err != nil {
381				return fmt.Errorf("failed to merge routing fragment: %w", err)
382			}
383		}
384	
385		// Scoped lists have identity and ordering semantics, so a supplied list is
386		// replaced as one unit. An omitted list remains untouched in merge mode.
387		for _, section := range []string{"entrypoints", "recipes"} {
388			if value := mappingValueNode(fragmentRoot, section); value != nil {
389				setMappingValueNode(baseRoot, section, value)
390			}
391		}
392		return nil
393	}
394	
395	func mergeFragmentGlobalNode(baseRoot *yaml.Node, fragment *globalFragment) error {
396		if fragment == nil || fragment.Services == nil || fragment.Services.RateLimit == nil {
397			return nil
398		}
399	
400		global, err := ensureMappingNode(baseRoot, "global")
401		if err != nil {
402			return err
403		}
404		services, err := ensureMappingNode(global, "services")
405		if err != nil {
406			return err
407		}
408		rateLimit := &yaml.Node{}
409		if err := rateLimit.Encode(fragment.Services.RateLimit); err != nil {
410			return fmt.Errorf("failed to encode global.services.ratelimit: %w", err)
411		}
412		setMappingValueNode(services, "ratelimit", rateLimit)
413		return nil
414	}
415	
416	func ensureMappingNode(parent *yaml.Node, key string) (*yaml.Node, error) {
417		value := mappingValueNode(parent, key)
418		if value == nil {
419			setMappingValueNode(parent, key, &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"})
420			value = mappingValueNode(parent, key)
421		}
422		if value.Kind != yaml.MappingNode {
423			return nil, fmt.Errorf("config %s block must be a YAML mapping", key)
424		}
425		return value, nil
426	}
427	
428	func mergeFragmentGlobal(base *routerconfig.CanonicalConfig, frag *globalFragment) {
429		if frag == nil || frag.Services == nil || frag.Services.RateLimit == nil {
430			return
431		}
432		if base.Global == nil {
433			base.Global = &routerconfig.CanonicalGlobal{}
434		}
435		base.Global.Services.RateLimit = *frag.Services.RateLimit
436	}
437	
438	func resolveDeployBaseYAML(currentData []byte, providedBase string) ([]byte, error) {
439		if strings.TrimSpace(providedBase) == "" {
440			return currentData, nil
441		}
442	
443		providedBaseBytes := []byte(providedBase)
444		if _, err := parseYAMLDocument(providedBaseBytes); err != nil {
445			return nil, fmt.Errorf("invalid imported base config: %w", err)
446		}
447		looksLikeFullBase, err := looksLikeFullCanonicalDeployBase(providedBaseBytes)
448		if err != nil {
449			return nil, fmt.Errorf("invalid imported base config: %w", err)
450		}
451		if !looksLikeFullBase {
452			return currentData, nil
453		}
454		return providedBaseBytes, nil
455	}
456	
457	func looksLikeFullCanonicalDeployBase(raw []byte) (bool, error) {
458		doc, err := parseYAMLDocument(raw)
459		if err != nil {
460			return false, err
461		}
462		root, err := documentMappingNode(doc)
463		if err != nil {
464			return false, err
465		}
466		if mappingValueNode(root, "routing") == nil {
467			return false, nil
468		}
469	
470		for _, key := range []string{"version", "listeners", "providers", "global"} {
471			if mappingValueNode(root, key) != nil {
472				return true, nil
473			}
474		}
475		return false, nil
476	}
477	
478	func rollbackDirectWrite(w http.ResponseWriter, configPath string, configDir string, version string) {
479		// Acquire deploy lock
480		if !deployMu.TryLock() {
481			w.Header().Set("Content-Type", "application/json")
482			w.WriteHeader(http.StatusConflict)
483			_ = json.NewEncoder(w).Encode(map[string]string{
484				"error":   "deploy_in_progress",
485				"message": "Another deploy operation is in progress.",
486			})
487			return
488		}
489		defer deployMu.Unlock()
490	
491		// Find backup file
492		backupData, err := readConfigBackup(configDir, version)
493		if err != nil {
494			w.Header().Set("Content-Type", "application/json")
495			w.WriteHeader(http.StatusNotFound)
496			_ = json.NewEncoder(w).Encode(map[string]string{
497				"error":   "version_not_found",
498				"message": fmt.Sprintf("Backup version %s not found", version),
499			})
500			return
501		}
502	
503		// Validate backup YAML syntax
504		if _, unmarshalErr := parseYAMLDocument(backupData); unmarshalErr != nil {
505			w.Header().Set("Content-Type", "application/json")
506			w.WriteHeader(http.StatusBadRequest)
507			_ = json.NewEncoder(w).Encode(map[string]string{
508				"error":   "backup_invalid",
509				"message": fmt.Sprintf("Backup config has invalid YAML: %v", unmarshalErr),
510			})
511			return
512		}
513	
514		// Back up current config before rollback
515		existingData := snapshotCurrentConfigBeforeRollback(configPath, configDir)
516	
517		// Atomic write to config.yaml
518		if err := writeConfigAtomically(configPath, backupData); err != nil {
519			http.Error(w, fmt.Sprintf("Failed to write config: %v", err), http.StatusInternalServerError)
520			return
521		}
522	
523		log.Printf("[Rollback] Config rolled back to version %s, written to %s", version, configPath)
524	
525		if err := applyWrittenConfig(configPath, configDir, existingData, true); err != nil {
526			http.Error(w, formatRuntimeApplyError("Failed to apply rolled back config to runtime", err), http.StatusInternalServerError)
527			return
528		}
529	
530		refreshConfigProjection(configprojection.RefreshInput{
531			Version:     version,
532			Source:      configprojection.SourceRollback,
533			YAMLBytes:   backupData,
534			DSLSnapshot: readArchivedDSL(configDir),
535		})
536	
537		w.Header().Set("Content-Type", "application/json")
538		_ = json.NewEncoder(w).Encode(DeployResponse{
539			Status:  "success",
540			Version: version,
541			Message: fmt.Sprintf("Rolled back to version %s. Router and Envoy have been updated.", version),
542		})
543	}
544	
545	// canonicalizeYAMLForDiff converts YAML into a normalized representation so
546	// order-only key changes do not produce noisy diffs in the preview modal.
547	func canonicalizeYAMLForDiff(raw []byte) string {
548		text := string(raw)
549		if strings.TrimSpace(text) == "" {
550			return text
551		}
552		if strings.Contains(text, "# No existing config") {
553			return text
554		}
555	
556		if looksLikeFullBase, err := looksLikeFullCanonicalDeployBase(raw); err == nil && looksLikeFullBase {
557			if configData, decodeErr := decodeYAMLTaggedBytes[routerconfig.CanonicalConfig](raw); decodeErr == nil {
558				if canonical, marshalErr := marshalYAMLBytes(configData); marshalErr == nil {
559					return string(canonical)
560				}
561			}
562		}
563		if fragment, err := decodeYAMLTaggedBytes[routingFragmentDocument](raw); err == nil {
564			if canonical, marshalErr := marshalYAMLBytes(fragment); marshalErr == nil {
565				return string(canonical)
566			}
567		}
568		return text
569	}
570

